<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="theme-color" content="#101820">
    <title>Catálogo | Nexo Informática</title>
    <style>
        :root{--ink:#17212b;--muted:#6b7785;--line:#e5e9ed;--paper:#fff;--canvas:#f5f7f8;--accent:#b9f36b;--dark:#101820}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:inherit;text-decoration:none}.topbar{background:var(--dark);color:white}.topbar-inner,.container{width:min(1120px,calc(100% - 40px));margin:auto}.topbar-inner{height:76px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;font-weight:750;letter-spacing:-.03em}.brand-mark{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:var(--accent);color:var(--dark);font-size:18px}.nav{display:flex;gap:28px;color:#b9c2cb;font-size:14px}.nav a:first-child{color:white}.hero{background:var(--dark);color:white;padding:56px 0 92px}.eyebrow{margin:0 0 13px;color:var(--accent);font-size:12px;font-weight:750;letter-spacing:.14em;text-transform:uppercase}.hero h1{max-width:700px;margin:0;font-size:clamp(34px,5vw,54px);line-height:1.04;letter-spacing:-.055em}.hero-copy{max-width:540px;margin:18px 0 0;color:#adb8c2;font-size:16px;line-height:1.65}.catalog{margin-top:-38px;padding-bottom:64px}.filters{display:grid;grid-template-columns:minmax(220px,1fr) minmax(190px,260px) auto;gap:12px;padding:18px;border:1px solid var(--line);border-radius:16px;background:var(--paper);box-shadow:0 12px 30px #1018200b}.field{height:48px;width:100%;padding:0 14px;border:1px solid var(--line);border-radius:9px;background:white;color:var(--ink);font:inherit;outline:none}.field:focus{border-color:#8290a0;box-shadow:0 0 0 3px #17212b0c}.search-wrap{position:relative}.search-wrap .field{padding-left:42px}.search-icon{position:absolute;left:15px;top:14px;color:#798590}.button{height:48px;padding:0 20px;border:0;border-radius:9px;background:var(--accent);color:var(--dark);font:700 14px inherit;cursor:pointer}.button:hover{background:#a9e65a}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:34px 0 15px}.section-head h2{margin:0;font-size:21px;letter-spacing:-.035em}.result-count{margin:5px 0 0;color:var(--muted);font-size:13px}.sort-label{color:var(--muted);font-size:13px}.sort-label strong{margin-left:5px;color:var(--ink);font-weight:600}.table-wrap{overflow:hidden;border:1px solid var(--line);border-radius:14px;background:var(--paper)}table{width:100%;border-collapse:collapse;text-align:left}thead{background:#fafbfc}th{padding:13px 18px;color:#78838e;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}td{padding:17px 18px;border-top:1px solid var(--line);font-size:14px}tbody tr:hover{background:#fcfdfb}.product-name{display:block;font-weight:650}.sku{display:block;margin-top:5px;color:var(--muted);font-size:12px}.category{display:inline-flex;padding:6px 10px;border-radius:20px;background:#f0f3f5;color:#47535e;font-size:12px;font-weight:550}.price{font-weight:650;white-space:nowrap}.stock{color:#58636e}.status{display:inline-flex;align-items:center;gap:7px;font-size:12px;font-weight:600;white-space:nowrap}.status:before{width:7px;height:7px;border-radius:50%;background:#35a56f;content:""}.status.inactive:before{background:#a0a8af}.status.inactive{color:#747e87}.empty{padding:56px 20px;text-align:center}.empty-icon{display:grid;place-items:center;width:46px;height:46px;margin:0 auto 14px;border-radius:13px;background:#f0f3f5;color:#697680;font-size:22px}.empty h3{margin:0;font-size:16px}.empty p{margin:7px 0 0;color:var(--muted);font-size:14px}.footer{padding:25px 0;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.footer-inner{display:flex;justify-content:space-between;gap:20px}
        @media(max-width:760px){.topbar-inner,.container{width:min(calc(100% - 28px),1120px)}.topbar-inner{height:66px}.nav{gap:16px}.nav a:not(:first-child){display:none}.hero{padding:43px 0 75px}.hero-copy{font-size:14px}.catalog{margin-top:-30px}.filters{grid-template-columns:1fr 1fr;padding:13px}.search-wrap{grid-column:1/-1}.button{width:100%}.section-head{margin-top:27px}th,td{padding:13px 12px}.category{font-size:11px;padding:5px 8px}}
        @media(max-width:460px){.filters{grid-template-columns:1fr}.search-wrap{grid-column:auto}.section-head{align-items:start;flex-direction:column}.sort-label{display:none}.table-wrap{overflow:visible;border:0;background:transparent}table,tbody{display:block}thead{display:none}tbody{display:grid;gap:10px}tr{display:grid;grid-template-columns:1fr auto;gap:9px;padding:15px;border:1px solid var(--line);border-radius:12px;background:white}td{padding:0;border:0}td:nth-child(2){grid-column:2;grid-row:1/3;align-self:start}td:nth-child(3){grid-column:1;grid-row:2}td:nth-child(4){grid-column:2;grid-row:3;text-align:right}td:nth-child(5){grid-column:1;grid-row:3}.footer-inner{flex-direction:column;gap:7px}}
    </style>
</head>
<body>
<header class="topbar"><div class="topbar-inner"><a class="brand" href="{{ route('productos.index') }}"><span class="brand-mark">N</span><span>NEXO<span style="color:var(--accent)">.</span></span></a><nav class="nav" aria-label="Navegación principal"><a href="{{ route('productos.index') }}">Catálogo</a><a href="#productos">Productos</a><a href="#contacto">Contacto</a></nav></div></header>
<main>
    <section class="hero"><div class="container"><p class="eyebrow">Tecnología para tu día a día</p><h1>Encuentra tu próximo<br>gran equipo.</h1><p class="hero-copy">Explora nuestra selección de informática: componentes, periféricos y equipos elegidos para rendir contigo.</p></div></section>
    <section class="container catalog" id="productos" aria-label="Catálogo de productos">
        <form class="filters" method="GET" action="{{ route('productos.index') }}">
            <label class="search-wrap"><span class="search-icon" aria-hidden="true">⌕</span><input class="field" type="search" name="q" value="{{ $busqueda }}" placeholder="Buscar por producto o SKU..." aria-label="Buscar por producto o SKU"></label>
            <label><select class="field" name="categoria" aria-label="Filtrar por categoría"><option value="">Todas las categorías</option>@foreach ($categorias as $categoria)<option value="{{ $categoria->id }}" @selected((string) $categoriaSeleccionada === (string) $categoria->id)>{{ $categoria->nombre }}</option>@endforeach</select></label>
            <button class="button" type="submit">Buscar productos</button>
        </form>
        <div class="section-head"><div><h2>Todos los productos</h2><p class="result-count">{{ $productos->count() }} {{ $productos->count() === 1 ? 'producto encontrado' : 'productos encontrados' }}</p></div><p class="sort-label">Ordenar por <strong>Nombre A–Z</strong></p></div>
        <div class="table-wrap">
            @if ($productos->isEmpty())
                <div class="empty"><div class="empty-icon" aria-hidden="true">⌕</div><h3>No se encontraron productos</h3><p>Prueba con otro nombre, SKU o categoría.</p></div>
            @else
                <table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th></tr></thead><tbody>
                @foreach ($productos as $producto)
                    <tr><td><span class="product-name">{{ $producto->nombre }}</span><span class="sku">{{ $producto->sku }}</span></td><td><span class="category">{{ $producto->categoria->nombre }}</span></td><td class="price">{{ number_format((float) $producto->precio, 2, ',', '.') }} €</td><td class="stock">{{ $producto->stock }} uds.</td><td><span class="status {{ $producto->activo ? '' : 'inactive' }}">{{ $producto->activo ? 'Activo' : 'Inactivo' }}</span></td></tr>
                @endforeach
                </tbody></table>
            @endif
        </div>
    </section>
</main>
<footer class="footer" id="contacto"><div class="container footer-inner"><span>© {{ date('Y') }} Nexo Informática</span><span>Tu tecnología, más cerca.</span></div></footer>
</body>
</html>
